    }
    fn lane(&self, name: &str) -> Result<usize> {
        match name {
            "native" => Ok(0),
            "nativefast" => Ok(if self.data.dense { 32 } else { 0 }),
            "gridnative" => Ok(32),
            "gridfp4x2" => Ok(34),
            "gridfp4x4" => Ok(36),
            "fp4x2" => Ok(2),
            "fp4x4" => Ok(4),
            "scalarfp4x2" => Ok(18),
            "scalarfp4x4" => Ok(20),
            "auto" => Ok(if self.data.dense && self.data.p >= 512 {
                34
