#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct Request {
    op: String,
    #[serde(default)]
    solve_id: u64,
    #[serde(default)]
    generation: u32,
    #[serde(default)]
    lane: String,
    #[serde(default)]
