    #[serde(default)]
    solve_id: u64,
    #[serde(default)]
    generation: u32,
    #[serde(default)]
    lane: String,
    #[serde(default)]
    tier: String,
    #[serde(default = "default_limit")]
    max_updates: u32,
    #[serde(default = "default_wall")]
    wall_ms: u64,
    #[serde(default = "default_audit")]
    audit_max: u32,
    #[serde(default)]
    cancel_after: Option<u32>,
    #[serde(default)]
    cancel_file: Option<String>,
    #[serde(default)]
    count: u32,
    #[serde(default)]
    limit: f64,
    #[serde(default)]
    raw: Option<Vec<f64>>,
    #[serde(default)]
    fault: Option<String>,
}
impl Request {
    fn cancelled(&self, physical: u32) -> bool {
        self.cancel_after.is_some_and(|v| physical >= v)
            || self
                .cancel_file
                .as_ref()
                .is_some_and(|p| Path::new(p).exists())
    }
}
struct Session {
