    put(BASE/'dependencies-v2.json',dict(status='passed',**result,lock=ref(ROOT/'research/lp-delivery4/Cargo.lock'),policy=ref(ROOT/'research/lp-delivery4/deny.toml'),source=ref(Path(__file__))))
    print(dict(status='passed',external=len(result['external']),local_wildcards=len(result['local_wildcards'])),flush=True)
