                let phase = Instant::now();
                self.pool
                    .get_mut(&k)
                    .unwrap()
                    .checkpoint(&self.module, &self.stream, true)?;
                *times.entry("rollback").or_default() += phase.elapsed().as_nanos();
                status = if r.cancelled(physical) {
                    "cancelled"
                } else {
                    "deadline"
                };
                break;
            }
            let e = self.pool.get_mut(&k).unwrap();
            let mut count = 32
                .min(interval - e.since_audit)
                .min(r.max_updates - physical);
            if let Some(cancel) = r.cancel_after {
                count = count.min(cancel.saturating_sub(physical));
            }
            let allowance = policy::allowance(observation.rho, tolerance, observation.scale);
            let phase = Instant::now();
            let step = e.run(&self.module, &self.stream, 1, count, allowance)?;
            *times.entry("iteration").or_default() += phase.elapsed().as_nanos();
            if step.done == 0 || step.done > count {
                return Err("physical work report".into());
            }
            physical += step.done;
            self.physical_total += u64::from(step.done);
            *work.entry(k).or_default() += step.done;
            gpu_us += step.gpu_us;
            let mut reason = if step.flags.iter().any(|v| *v != 0) {
                Some(if step.flags.contains(&5) {
                    "projection_ambiguous"
                } else if step.flags.contains(&1) || step.flags.contains(&2) {
                    "nonfinite"
                } else {
                    "local_budget"
                })
            } else {
                None
            };
            for terms in step.terms.chunks(8) {
                local_estimate = local_estimate.max(terms[..7].iter().map(|v| f64::from(*v)).sum());
            }
            events.push(json!({"kind":"window","lane":k,"physical":physical,"logical":e.logical,"step":step}));
            // Cancellation/deadline wins at a completed device boundary, before certification.
            if r.cancelled(physical) || start.elapsed().as_millis() >= u128::from(r.wall_ms) {
                let phase = Instant::now();
                e.checkpoint(&self.module, &self.stream, true)?;
                *times.entry("rollback").or_default() += phase.elapsed().as_nanos();
                status = if r.cancelled(physical) {
                    "cancelled"
                } else {
                    "deadline"
                };
                break;
            }
            if !fault_used && r.fault.as_deref() == Some("local_budget") {
                reason = Some("local_budget");
                fault_used = true;
            }
            if !fault_used && r.fault.as_deref() == Some("conversion_failure") {
                reason = Some("local_budget");
            }
            if reason != Some("nonfinite")
                && (e.since_audit >= interval || physical == r.max_updates || reason.is_some())
            {
                let phase = Instant::now();
                raw = e.raw(&self.module, &self.stream)?;
                *times.entry("export").or_default() += phase.elapsed().as_nanos();
                let phase = Instant::now();
                observation = self.data.observe(&raw)?;
                *times.entry("audit").or_default() += phase.elapsed().as_nanos();
                let endpoint = self.data.endpoint(&raw, "completed");
                let phase = Instant::now();
                let certificate = self.checker.assess(&endpoint, &r.tier)?;
                *times.entry("checker").or_default() += phase.elapsed().as_nanos();
                let accepted = certificate["accepted"] == true;
                audits.push(json!({"physical":physical,"logical":e.logical,"trigger":reason.unwrap_or("periodic"),"observation":observation,"endpoint":endpoint,"certificate":certificate}));
                checked_endpoint = Some(endpoint);
                final_certificate = Some(certificate);
                if accepted {
                    status = "certified";
                    break;
                }
                if reason.is_none() {
                    // Noise is the unrepresented arithmetic estimate, NOT the retained tail.
                    stalls = policy::stalled(accepted_rho, observation.rho, local_estimate, stalls);
                    if k % 16 != 0 && observation.rho > 2. * accepted_rho.max(tolerance) {
                        reason = Some("residual_growth");
                    } else if k % 16 != 0 && stalls >= 3 {
                        reason = Some("noise_limited_stagnation");
                    } else {
                        let phase = Instant::now();
                        e.checkpoint(&self.module, &self.stream, false)?;
                        *times.entry("checkpoint").or_default() += phase.elapsed().as_nanos();
                        accepted_rho = observation.rho;
                        saved_observation = observation.clone();
                        saved_logical = e.logical;
                        saved_stalls = stalls;
                        interval =
                            policy::audit_interval(observation.rho, local_estimate, r.audit_max);
                        if (16..32).contains(&k)
                            && local_estimate
                                > policy::allowance(observation.rho, tolerance, observation.scale)
                        {
                            reason = Some("anticipated_local_budget");
                        }
                        local_estimate = 0.;
                    }
                }
            }
            if let Some(reason) = reason {
                if k % 16 == 0 {
                    let phase = Instant::now();
                    self.pool
                        .get_mut(&k)
                        .unwrap()
                        .checkpoint(&self.module, &self.stream, true)?;
                    *times.entry("rollback").or_default() += phase.elapsed().as_nanos();
                    status = "numerical_failure";
                    break;
                }
                let phase = Instant::now();
                let e = self.pool.get_mut(&k).unwrap();
                e.checkpoint(&self.module, &self.stream, true)?;
                let restored = e.raw(&self.module, &self.stream)?;
                let generation = e.generation;
                if e.logical != saved_logical {
                    return Err("rollback controller mismatch".into());
                }
                *times.entry("rollback").or_default() += phase.elapsed().as_nanos();
                let old = k;
                let mut next = match k {
                    2 => 4,
                    18 => 20,
                    34 => 36,
                    36 => 32,
                    _ => 0,
                };
                let phase = Instant::now();
                self.prepare(next)?;
                let mut conversion_input = restored.clone();
                if !fault_used && r.fault.as_deref() == Some("conversion_failure") {
                    conversion_input[0] = f64::MAX;
                    fault_used = true;
                }
                let conversion = self.pool.get_mut(&next).unwrap().reset(
                    &self.module,
                    &self.stream,
                    &conversion_input,
                    saved_logical,
                    generation,
                );
                let changed = conversion.is_err()
                    || self.pool[&next].raw(&self.module, &self.stream)? != restored;
                if changed {
                    events.push(json!({"kind":"conversion_failure","from":old,"attempted":next,"physical":physical}));
                    fault_used = true;
                    next = 0;
                    self.prepare(next)?;
                    self.pool.get_mut(&next).unwrap().reset(
                        &self.module,
                        &self.stream,
                        &restored,
                        saved_logical,
                        generation,
                    )?;
                    if self.pool[&next].raw(&self.module, &self.stream)? != restored {
                        return Err("native conversion changed checkpoint".into());
                    }
                }
                *times.entry("conversion").or_default() += phase.elapsed().as_nanos();
                k = next;
                observation = saved_observation.clone();
                accepted_rho = observation.rho;
                stalls = saved_stalls;
                interval = policy::audit_interval(observation.rho, 0., r.audit_max);
                local_estimate = 0.;
                events.push(json!({"kind":"recovery","reason":reason,"from":old,"to":k,"physical":physical,"logical":saved_logical,"generation":generation}));
            }
        }
        let phase = Instant::now();
        let terminal = self.pool[&k].snapshot(&self.module, &self.stream)?;
        let saved = self.pool[&k].saved_snapshot(&self.stream)?;
        *times.entry("export").or_default() += phase.elapsed().as_nanos();
        let transport = match status {
            "cancelled" => "cancelled",
            "deadline" => "limit",
            "numerical_failure" => "error",
            "unbounded_direction" => "refused",
            _ => "completed",
        };
        let endpoint = self.data.endpoint(&terminal.raw, transport);
        if checked_endpoint.as_ref() != Some(&endpoint) {
            let phase = Instant::now();
            final_certificate = Some(self.checker.assess(&endpoint, &r.tier)?);
            *times.entry("checker").or_default() += phase.elapsed().as_nanos();
        }
        let certificate = final_certificate.ok_or("missing independent certificate")?;
        if status == "limit" && certificate["accepted"] == true {
            status = "certified";
        }
        let elapsed = start.elapsed().as_nanos();
        let assigned: u128 = times.values().sum();
        times.insert(
            "coordination",
            elapsed.checked_sub(assigned).ok_or("overlapping phases")?,
        );
        let result = json!({"schema_version":1,"kind":"lp-fp4-accel-solve","solve_id":self.solve_id,"status":status,"certified":certificate["accepted"],"lane":r.lane,"final_lane":k,"tier":r.tier,
            "physical":physical,"logical":terminal.logical,"physical_total":self.physical_total,"attempted":work,"gpu_us":gpu_us,"solve_ns":elapsed,"costs_ns":times,"setup_ns":self.setup_ns,
            "model_sha256":self.data.hash,"image_sha256":self.image,"checker_binary_sha256":self.checker.binary,"row_scale":self.data.row_scale,"shift":self.data.shift,
            "endpoint":endpoint,"certificate":certificate,"audits":audits,"events":events,
            "checkpoint":{"device":saved,"accepted_observation":saved_observation,"stalls":saved_stalls,"logical":saved_logical,"physical_outside_rollback":physical},"terminal":terminal,
            "representation":if work.keys().all(|k|k%16==0) {"FP64 state and products"} else {"FP32-pair state; FP4 increment products with original-coefficient FP64 references per <=32 updates, or explicitly selected scalar correction; native recovery recorded in attempted; operational estimates"}});
        self.cancelled = status == "cancelled";
        self.solve_id = self
            .solve_id
            .checked_add(1)
            .ok_or("solve identity overflow")?;
        Ok(result)
    }
    fn command(&mut self, r: Request) -> Result<Value> {
        if self.cancelled {
            return Err("cancelled service is terminal".into());
        }
        if r.solve_id != self.solve_id {
            return Err("stale solve identity".into());
        }
        if r.op == "prepare" {
            let k = self.lane(&r.lane)?;
            self.prepare(k)?;
            return Ok(json!({"prepared":k,"solve_id":self.solve_id}));
        }
        if r.op == "solve" {
            return self.solve(&r);
        }
        if r.op == "debug_reset" {
            if self.debug.is_some() {
                return Err("active debug solve must finish before reset".into());
            }
            let k = self.lane(&r.lane)?;
            self.prepare(k)?;
            let raw = r.raw.as_ref().unwrap_or(&self.data.initial);
            self.pool
                .get_mut(&k)
                .unwrap()
                .reset(&self.module, &self.stream, raw, 0, 0)?;
            self.debug = Some(k);
            self.debug_physical = 0;
            self.debug_cap = r.max_updates;
            return Ok(
                json!({"reset":true,"generation":0,"shift":self.data.shift,"row_scale":self.data.row_scale}),
            );
        }
        let k = self.debug.ok_or("debug state not loaded")?;
        let e = self.pool.get_mut(&k).unwrap();
        if r.generation != e.generation {
            return Err("stale generation".into());
        }
        match r.op.as_str() {
            "debug_forward" | "debug_transpose" => {
                Ok(json!({"product":e.product(&self.module,&self.stream,r.op=="debug_transpose")?}))
            }
            "debug_step" => {
                if self.debug_physical + r.count > self.debug_cap {
                    return Err("physical cap".into());
                }
                let step = e.run(&self.module, &self.stream, 1, r.count, r.limit)?;
                self.debug_physical += step.done;
                Ok(
                    json!({"step":step,"logical":e.logical,"physical":self.debug_physical,"generation":e.generation}),
                )
            }
            "debug_saved" => Ok(serde_json::to_value(e.saved_snapshot(&self.stream)?)?),
            "debug_export" => Ok(serde_json::to_value(
                e.snapshot(&self.module, &self.stream)?,
            )?),
            "debug_restore" | "debug_save" => {
                e.checkpoint(&self.module, &self.stream, r.op == "debug_restore")?;
                Ok(json!({"generation":e.generation,"logical":e.logical}))
            }
            "debug_finish" => {
                self.debug = None;
                self.solve_id += 1;
                Ok(json!({"solve_id":self.solve_id}))
            }
            _ => Err("unknown command".into()),
        }
    }
}
fn main() -> Result<()> {
    config::init()?;
    let profile = config::get().profile;
    let costs = if profile {
        Some(optimizer_core::lp_cost::Session::begin()?)
    } else {
        None
    };
    let started = Instant::now();
    let result = program();
    if let Some(costs) = costs {
        eprintln!(
            "{}",
            json!({"delivery4_process":{"role":std::env::args().nth(1),"main_ns":started.elapsed().as_nanos(),"success":result.is_ok(),"costs":costs.finish()}})
        );
    }
    result
}
fn program() -> Result<()> {
    let a: Vec<_> = std::env::args().collect();
    if a.get(1).map(String::as_str) == Some("startup-profile") {
        return startup::run(&a);
    }
    if a.get(1).map(String::as_str) == Some("transport-profile") {
        return transport::profile(&a);
    }
    if a.get(1).map(String::as_str) == Some("profile") {
        return profile::run(&a);
    }
    if a.len() >= 3 && a[1] == "inspect" {
        let d = Data::new(&fs::read(&a[2])?, !a.iter().any(|x| x == "unscaled"))?;
        return emit(
            &json!({"n":d.original.column_count(),"m":d.original.row_count(),"p":d.p,"a":d.a,"initial":d.initial,"row_scale":d.row_scale,"shift":d.shift,"unbounded_direction":d.unbounded_direction,"packs":{"2":d.pack(2)?,"4":d.pack(4)?}}),
        );
    }
    if a.len() == 3 && a[1] == "check-service" {
        return check_service(Path::new(&a[2]));
    }
    if a.len() == 6 && ["check", "check-serial"].contains(&a[1].as_str()) {
        let bytes = fs::read(&a[2])?;
        let e: Endpoint = serde_json::from_slice(&fs::read(&a[3])?)?;
        let c = checker::Checker::new(&bytes)?;
        let mut result = if a[1] == "check-serial" {
            c.assess_serial(&e, &a[4])?
        } else {
            c.assess(&e, &a[4])?
        };
        result["checker_binary_sha256"] = json!(hex(&fs::read(std::env::current_exe()?)?));
        let mut f = fs::OpenOptions::new()
            .write(true)
            .create_new(true)
            .open(&a[5])?;
        serde_json::to_writer(&mut f, &result)?;
        f.write_all(b"\n")?;
        f.sync_all()?;
        return Ok(());
    }
    if a.len() >= 4 && ["serve", "once"].contains(&a[1].as_str()) {
        let setup_scope = optimizer_core::lp_cost::scope("session_setup");
        let mut s = Session::new(
            Path::new(&a[2]),
            Path::new(&a[3]),
            !a.iter().any(|x| x == "unscaled"),
        )?;
        drop(setup_scope);
        if a[1] == "once" {
            let r: Request = serde_json::from_slice(&fs::read(a.get(4).ok_or("request file")?)?)?;
            let responding = optimizer_core::lp_cost::scope("response_construction");
            let response = s.respond(r)?;
            drop(responding);
            let output = optimizer_core::lp_cost::scope("response_emit");
            emit(&response)?;
            drop(output);
            let destruction = optimizer_core::lp_cost::scope("session_destruction");
            drop(s);
            drop(destruction);
            return Ok(());
        }
        emit(
            &json!({"ready":true,"model_sha256":s.data.hash,"setup_ns":s.setup_ns,"solve_id":0,"delivery_variant":config::get().name,"delivery_profile":if config::get().profile {s.setup_profile.clone()} else {Value::Null}}),
        )?;
        let mut input = io::stdin().lock();
        loop {
            let mut line = String::new();
            let got = (&mut input).take((8 << 20) + 1).read_line(&mut line)?;
            if got == 0 {
                break;
            }
            if got > 8 << 20 {
                return Err("command frame limit".into());
            }
            let r: Request = serde_json::from_str(&line)?;
            let responding = optimizer_core::lp_cost::scope("response_construction");
            let response = s.respond(r)?;
            drop(responding);
            let output = optimizer_core::lp_cost::scope("response_emit");
            emit(&response)?;
            drop(output);
        }
        let destruction = optimizer_core::lp_cost::scope("session_destruction");
        drop(s);
        drop(destruction);
        return Ok(());
    }
    Err("usage: serve IMAGE MODEL [unscaled] | once IMAGE MODEL REQUEST [unscaled] | check-service MODEL | check MODEL ENDPOINT TIER OUTPUT".into())
}

use crate::Result;
use crate::identity::hex;
use optimizer_core::Model;
use optimizer_lp::LinearProgram;
use serde::Serialize;

pub const MAX: usize = 512;
pub fn pair(x: f64) -> [f32; 2] {
    let h = x as f32;
    [h, (x - f64::from(h)) as f32]
}
pub fn decode(c: u32) -> f64 {
    let value = [0., 0.5, 1., 1.5, 2., 3., 4., 6.][(c & 7) as usize];
    if c & 8 == 0 { value } else { -value }
}
pub fn encode(values: &[f64], k: usize) -> Result<(Vec<u32>, Vec<i32>, Vec<f64>)> {
    if !values.len().is_multiple_of(32)
        || ![2, 4].contains(&k)
        || values.iter().any(|v| !v.is_finite())
    {
        return Err("encoding domain".into());
    }
    let mut residual = values.to_vec();
    let mut words = vec![0; k * values.len() / 8];
    let mut exponents = Vec::new();
    for plane in 0..k {
        let maximum = residual.iter().map(|x| x.abs()).fold(0., f64::max);
        if maximum > 6. * 2_f64.powi(48) {
            return Err("encoding scale overflow".into());
        }
        let mut e = if maximum == 0. {
            -48
        } else {
            (maximum.log2().floor() as i32 - 2).max(-48)
        };
        if maximum > 6. * 2_f64.powi(e) {
            e += 1;
        }
        exponents.push(e);
        let scale = 2_f64.powi(e);
        for (i, r) in residual.iter_mut().enumerate() {
            let x = r.abs() / scale;
            let mut code = 0_u32;
            for (j, mid) in [0.25, 0.75, 1.25, 1.75, 2.5, 3.5, 5.].iter().enumerate() {
                if x > *mid || (x == *mid && j % 2 == 1) {
                    code = (j + 1) as u32;
                }
            }
            if *r < 0. && code != 0 {
                code |= 8;
            }
            words[plane * values.len() / 8 + i / 8] |= code << ((i % 8) * 4);
            *r -= decode(code) * scale;
        }
    }
    Ok((words, exponents, residual))
}

pub struct Data {
    pub original: LinearProgram,
    pub hash: String,
    pub p: usize,
    pub a: Vec<f64>,
    pub cb: Vec<f64>,
    pub initial: Vec<f64>,
    pub row_scale: Vec<f64>,
    pub shift: u32,
    pub dense: bool,
    pub unbounded_direction: Option<usize>,
}
#[derive(Serialize)]
pub struct Packed {
    pub codes: Vec<u32>,
    pub exponents: Vec<i32>,
    pub original: Vec<[f32; 2]>,
    pub error: Vec<[f32; 2]>,
    pub native: Vec<f64>,
    pub cb: Vec<f64>,
    pub has_error: bool,
}
#[derive(Serialize, Clone, Debug)]
pub struct Observation {
    pub rho: f64,
    pub row: f64,
    pub column: f64,
    pub primal_fixed: f64,
    pub dual_fixed: f64,
    pub scale: f64,
}
impl Data {
    pub fn new(bytes: &[u8], equilibrate: bool) -> Result<Self> {
        let model = Model::from_json(bytes)?;
        let original = LinearProgram::new(&model)?;
        let (n, m) = (original.column_count(), original.row_count());
        if n == 0 || m == 0 || n.max(m) > MAX {
            return Err("bounded model dimensions".into());
        }
        let p = n.max(m).div_ceil(32) * 32;
        let mut row_scale = vec![1.; m];
        for (i, scale) in row_scale.iter_mut().enumerate() {
            let maximum = original
                .row_major()
                .line(i)
                .1
                .iter()
                .map(|v| v.abs())
                .fold(0., f64::max);
            if equilibrate && maximum > 0. {
                let exponent = -(maximum.log2().round() as i32);
                if !(-32..=32).contains(&exponent) {
                    return Err("row scaling domain".into());
                }
                *scale = 2_f64.powi(exponent);
            }
        }
        let mut a = vec![0.; p * p];
        for (i, j, v) in original.row_major().entries() {
            let scaled = v * row_scale[i];
            if !scaled.is_finite() || (v != 0. && scaled == 0.) {
                return Err("row scaling coefficient overflow/underflow".into());
            }
            a[i * p + j as usize] = scaled;
        }
        let mut cb = vec![0.; 5 * p + 5];
        cb[..n].copy_from_slice(original.objective());
        for (i, b) in original.columns().iter().enumerate() {
            cb[p + i] = b.lower;
            cb[2 * p + i] = b.upper;
        }
        for (i, b) in original.rows().iter().enumerate() {
            for (slot, bound) in [(3 * p + i, b.lower), (4 * p + i, b.upper)] {
                let scaled = bound * row_scale[i];
                if bound.is_finite() && (!scaled.is_finite() || (bound != 0. && scaled == 0.)) {
                    return Err("row scaling bound overflow/underflow".into());
                }
                cb[slot] = scaled;
            }
        }
        if cb[..5 * p]
            .iter()
            .filter(|x| x.is_finite())
            .any(|x| !(*x as f32).is_finite())
        {
            return Err("FP32-pair coefficient domain".into());
        }
        let nr = (0..p)
            .map(|i| a[i * p..(i + 1) * p].iter().map(|v| v.abs()).sum::<f64>())
            .fold(0., f64::max);
        let nc = (0..p)
            .map(|j| (0..p).map(|i| a[i * p + j].abs()).sum::<f64>())
            .fold(0., f64::max);
        let shift = (((nr * nc / 0.75).sqrt()).log2().ceil() as u32).max(1);
        if shift > 24 || a.iter().any(|v| !v.is_finite()) || cb.iter().any(|v| v.is_nan()) {
            return Err("scaled operator domain".into());
        }
        cb[5 * p] = nr;
        cb[5 * p + 1] = nc;
        cb[5 * p + 2] = cb[..5 * p]
            .iter()
            .filter(|v| v.is_finite())
            .map(|&v| {
                let q = pair(v);
                (v - f64::from(q[0]) - f64::from(q[1])).abs()
            })
            .fold(0., f64::max);
        cb[5 * p + 4] = original.nonzeros() as f64;
        let dense = original.nonzeros() as f64 / (n * m) as f64 > 0.2;
        let mut initial = vec![0.; 5 * p];
        for i in 0..n {
            initial[i] = ((i % 3) as f64 - 1.)
                .mul_add(0.125, 0.)
                .clamp(cb[p + i], cb[2 * p + i]);
            initial[2 * p + i] = initial[i];
            initial[3 * p + i] = initial[i];
        }
        for i in 0..m {
            initial[p + i] = ((i % 7) as f64 - 3.) / 64. / row_scale[i];
            initial[4 * p + i] = initial[p + i];
        }
        let unbounded_direction = (0..n).find(|&j| {
            original.column_major().line(j).1.is_empty()
                && ((original.objective()[j] > 0.
                    && original.columns()[j].lower == f64::NEG_INFINITY)
                    || (original.objective()[j] < 0.
                        && original.columns()[j].upper == f64::INFINITY))
        });
        Ok(Self {
            original,
            hash: hex(bytes),
            p,
            a,
            cb,
            initial,
            row_scale,
            shift,
            dense,
            unbounded_direction,
        })
    }
    pub fn pack(&self, k: usize) -> Result<Packed> {
        self.pack_mode(k, true, true)
    }
    pub fn pack_mode(&self, k: usize, correction: bool, sparse: bool) -> Result<Packed> {
        let p = self.p;
        let b = p / 32;
        let mut codes = Vec::new();
        let mut exponents = Vec::new();
        let mut errors = vec![0.; p * p];
        if k != 0 {
            for r in 0..b {
                for c in 0..b {
                    let tile: Vec<_> = (0..1024)
                        .map(|i| self.a[(r * 32 + i / 32) * p + c * 32 + i % 32])
                        .collect();
                    let (words, scales, error) = encode(&tile, k)?;
                    codes.extend(words);
                    exponents.extend(scales);
                    for i in 0..1024 {
                        errors[(r * 32 + i / 32) * p + c * 32 + i % 32] = error[i];
                    }
                }
            }
        } else {
            codes.push(0);
            exponents.push(0);
        }
        let mut native = Vec::with_capacity(2 * p * p);
        let mut error = Vec::with_capacity(2 * p * p);
        for transpose in [false, true] {
            for j in 0..p {
                for i in 0..p {
                    let index = if transpose { j * p + i } else { i * p + j };
                    native.push(self.a[index]);
                    if correction {
                        error.push(pair(errors[index]));
                    }
                }
            }
        }
        let original = if correction {
            native.iter().map(|&v| pair(v)).collect()
        } else {
            vec![]
        };
        if sparse {
            for transpose in [false, true] {
                let mut offsets = vec![0.];
                let mut indices = Vec::new();
                let mut values = Vec::new();
                for i in 0..p {
                    for j in 0..p {
                        let v = self.a[if transpose { j * p + i } else { i * p + j }];
                        if v != 0. {
                            indices.push(j as f64);
                            values.push(v);
                        }
                    }
                    offsets.push(indices.len() as f64);
                }
                native.extend(offsets);
                native.extend(indices);
                native.extend(values);
            }
        }
        let mut cb = self.cb.clone();
        cb[5 * p + 3] = (0..p)
            .map(|i| {
                errors[i * p..(i + 1) * p]
                    .iter()
                    .map(|v| v.abs())
                    .sum::<f64>()
            })
            .fold(0., f64::max)
            .max(
                (0..p)
                    .map(|j| (0..p).map(|i| errors[i * p + j].abs()).sum::<f64>())
                    .fold(0., f64::max),
            );
        Ok(Packed {
            codes,
            exponents,
            original,
            error,
            native,
            cb,
            has_error: errors.iter().any(|v| *v != 0.),
        })
    }
    pub fn endpoint(&self, raw: &[f64], transport: &str) -> crate::checker::Endpoint {
        crate::checker::Endpoint {
            model_sha256: self.hash.clone(),
            primal: raw[..self.original.column_count()].to_vec(),
            dual: (0..self.original.row_count())
                .map(|i| raw[self.p + i] * self.row_scale[i])
                .collect(),
            transport: transport.into(),
        }
    }
    pub fn observe(&self, raw: &[f64]) -> Result<Observation> {
        if raw.len() != 5 * self.p || raw.iter().any(|v| !v.is_finite()) {
            return Err("nonfinite audit".into());
        }
        let e = self.endpoint(raw, "completed");
        let (x, y) = (&e.primal, &e.dual);
        let mut ax = vec![0.; y.len()];
        let mut reduced = self.original.objective().to_vec();
        for (i, j, a) in self.original.row_major().entries() {
            ax[i] += a * x[j as usize];
            reduced[j as usize] -= a * y[i];
        }
        let sx = x
            .iter()
            .chain(&reduced)
            .map(|v| v.abs())
            .chain(
                self.original
                    .columns()
                    .iter()
                    .flat_map(|b| [b.lower, b.upper])
                    .filter(|v| v.is_finite())
                    .map(f64::abs),
            )
            .fold(1., f64::max);
        let sy = y
            .iter()
            .chain(&ax)
            .map(|v| v.abs())
            .chain(
                self.original
                    .rows()
                    .iter()
                    .flat_map(|b| [b.lower, b.upper])
                    .filter(|v| v.is_finite())
                    .map(f64::abs),
            )
            .fold(1., f64::max);
        let column = self
            .original
            .columns()
            .iter()
            .enumerate()
            .map(|(i, b)| (x[i] - x[i].clamp(b.lower, b.upper)).abs() / sx)
            .fold(0., f64::max);
        let primal_fixed = self
            .original
            .columns()
            .iter()
            .enumerate()
            .map(|(i, b)| (x[i] - (x[i] - reduced[i]).clamp(b.lower, b.upper)).abs() / sx)
            .fold(0., f64::max);
        let row = self
            .original
            .rows()
            .iter()
            .enumerate()
            .map(|(i, b)| (ax[i] - ax[i].clamp(b.lower, b.upper)).abs() / sy)
            .fold(0., f64::max);
        let dual_fixed = self
            .original
            .rows()
            .iter()
            .enumerate()
            .map(|(i, b)| (ax[i] + (y[i] - ax[i]).clamp(-b.upper, -b.lower)).abs() / sy)
            .fold(0., f64::max);
        let scale = raw[..self.p]
            .iter()
            .map(|v| v.abs())
            .fold(1., f64::max)
            .min(
                raw[self.p..2 * self.p]
                    .iter()
                    .map(|v| v.abs())
                    .fold(1., f64::max),
            );
        Ok(Observation {
            rho: row.max(column).max(primal_fixed).max(dual_fixed),
            row,
            column,
            primal_fixed,
            dual_fixed,
            scale,
        })
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn tie_even_and_negative_zero() {
        let mut v = vec![0.; 32];
        v[0] = 6.;
        v[1] = 0.25;
        v[2] = 0.75;
        v[3] = -0.25;
        let (w, e, r) = encode(&v, 2).unwrap();
        assert_eq!(e[0], 0);
        assert_eq!(w[0] & 0xffff, 0x0207);
        assert_eq!(r[0], 0.);
    }
    #[test]
    fn exact_residual_identity() {
        let v: Vec<_> = (0..1024)
            .map(|i| ((13 * i + 7) % 37) as f64 / 37. - 0.5)
            .collect();
        for k in [2, 4] {
            let (w, e, r) = encode(&v, k).unwrap();
            for i in 0..1024 {
                let decoded = (0..k)
                    .map(|j| decode((w[j * 128 + i / 8] >> ((i % 8) * 4)) & 15) * 2_f64.powi(e[j]))
                    .sum::<f64>();
                assert_eq!(v[i], decoded + r[i]);
            }
        }
    }
    #[test]
    fn encoding_rejects_nonfinite_and_overflow() {
        assert!(encode(&[f64::NAN; 32], 4).is_err());
        assert!(encode(&[1e100; 32], 4).is_err());
        assert!(encode(&[1.; 32], 8).is_err());
    }
}

//! CPU-only attribution of unchanged preparation and exact byte binding.
use crate::identity::hex;
use crate::{Result, checker::Checker, model::Data};
use optimizer_core::{Model, lp_cost};
use optimizer_lp::LinearProgram;
use serde_json::json;
use std::{fs, hint::black_box, io::Write, time::Instant};

pub fn run(a: &[String]) -> Result<()> {
    if a.len() != 6 {
        return Err("startup-profile MODEL IMAGE COUNT OUTPUT".into());
    }
    let count: usize = a[4].parse()?;
    if !(1..=32).contains(&count) {
        return Err("profile count".into());
    }
    let bytes = fs::read(&a[2])?;
    let image = fs::read(&a[3])?;
    let executable = fs::read(std::env::current_exe()?)?;
    let mut rows = Vec::new();
    for repetition in 0..count {
        let order = if repetition % 2 == 0 {
            [0, 1, 2, 3, 4, 5]
        } else {
            [5, 4, 3, 2, 1, 0]
        };
        for operation in order {
            let session = lp_cost::Session::begin()?;
            let start = Instant::now();
            let label = match operation {
                0 => {
                    black_box(Data::new(black_box(&bytes), true)?);
                    "solver_data"
                }
                1 => {
                    black_box(Checker::new(black_box(&bytes))?);
                    "checker_data"
                }
                2 => {
                    let model = Model::from_json(black_box(&bytes))?;
                    black_box(LinearProgram::new(&model)?);
                    "parse_and_lp"
                }
                3 => {
                    black_box(hex(black_box(&bytes)));
                    "model_hash"
                }
                4 => {
                    black_box(hex(black_box(&image)));
                    "image_hash"
                }
                _ => {
                    black_box(hex(black_box(&executable)));
                    "executable_hash"
                }
            };
            let elapsed = start.elapsed().as_nanos();
            rows.push(json!({"operation":label,"repetition":repetition,"ns":elapsed,"costs":session.finish()}));
        }
    }
    let mut f = fs::OpenOptions::new()
        .create_new(true)
        .write(true)
        .open(&a[5])?;
    serde_json::to_writer(
        &mut f,
        &json!({"rows":rows,"model_sha256":hex(&bytes),"model_bytes":bytes.len(),"image_sha256":hex(&image),"executable_sha256":hex(&executable),"image_bytes":image.len(),"executable_bytes":executable.len()}),
    )?;
    f.write_all(b"\n")?;
    f.sync_all()?;
    Ok(())
}

//! Delivery-only pipe batching and eager independent-checker startup.
//! Endpoint serialization and every assessment still use the retained checker.
use crate::identity::hex;
use crate::{Result, checker, checker::Endpoint, config};
use serde::{Deserialize, Serialize};
use serde_json::{Value, json};
use std::{
    fs,
    io::{self, BufRead, BufReader, Read, Write},
    path::Path,
    process::{Child, ChildStdin, ChildStdout, Command, Stdio},
    time::{Duration, Instant},
};
const FRAME_LIMIT: u64 = 8 << 20;

pub fn control() -> bool {
    !config::get().batch
}

// Read at most the admitted frame plus one byte; never allocate an unbounded
// line before checking its length. A partial final line is a transport failure.
fn frame(input: &mut impl BufRead) -> Result<Option<Vec<u8>>> {
    let mut bytes = Vec::new();
    let n = input.take(FRAME_LIMIT + 1).read_until(b'\n', &mut bytes)?;
    if n == 0 {
        return Ok(None);
    }
    if n as u64 > FRAME_LIMIT || bytes.last() != Some(&b'\n') {
        return Err("checker frame limit or truncated frame".into());
    }
    Ok(Some(bytes))
}

fn send(output: &mut impl Write, value: &impl Serialize, baseline: bool) -> Result<()> {
    if baseline {
        serde_json::to_writer(&mut *output, value)?;
        output.write_all(b"\n")?;
    } else {
        let mut bytes = serde_json::to_vec(value)?;
        bytes.push(b'\n');
        if bytes.len() as u64 > FRAME_LIMIT {
            return Err("checker outgoing frame limit".into());
        }
        output.write_all(&bytes)?;
    }
    output.flush()?;
    Ok(())
}

pub struct Independent {
    child: Child,
    input: Option<ChildStdin>,
    output: BufReader<ChildStdout>,
    pub binary: String,
    baseline: bool,
    failed: bool,
    started: Instant,
    ready_ns: u128,
    profiles: Vec<Value>,
}
impl Independent {
    // The owned guard exists before readiness: setup failures still close/reap
    // the checker, including failures in subsequent CUDA initialization.
    pub fn spawn(path: &Path) -> Result<Self> {
        let started = Instant::now();
        let mut child = Command::new(std::env::current_exe()?)
            .arg("check-service")
            .arg(path)
            .env("CUDA_VISIBLE_DEVICES", "")
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .spawn()?;
        let input = child.stdin.take();
        let output = BufReader::new(child.stdout.take().ok_or("checker stdout")?);
        Ok(Self {
            child,
            input,
            output,
            binary: String::new(),
            baseline: control(),
            failed: false,
            started,
            ready_ns: 0,
            profiles: Vec::new(),
        })
    }
    pub fn ready(&mut self, model_hash: &str) -> Result<()> {
        let ready = self.read()?;
        if ready["ready"] != true || ready["model_sha256"] != model_hash {
            return Err("checker model binding".into());
        }
        self.binary = ready["checker_binary_sha256"]
            .as_str()
            .ok_or("checker image")?
            .into();
        if self.binary.len() != 64 || !self.binary.bytes().all(|b| b.is_ascii_hexdigit()) {
            return Err("checker image digest".into());
        }
        self.ready_ns = self.started.elapsed().as_nanos();
        Ok(())
    }
    pub fn ready_elapsed_ns(&self) -> u128 {
        self.ready_ns
    }
    pub fn take_profile(&mut self) -> Vec<Value> {
        std::mem::take(&mut self.profiles)
    }
    fn read(&mut self) -> Result<Value> {
        let bytes = frame(&mut self.output)?.ok_or("checker ended")?;
        Ok(serde_json::from_slice(&bytes)?)
    }
    pub fn assess(&mut self, endpoint: &Endpoint, tier: &str) -> Result<Value> {
        if self.failed || self.binary.is_empty() {
            return Err("checker unavailable".into());
        }
        // Poison the connection until a fully bound response arrives; a partial
        // write or stale response can never become a later successful request.
        self.failed = true;
        let started = config::get().profile.then(Instant::now);
        let input = self.input.as_mut().ok_or("closed checker")?;
        if self.baseline {
            send(input, &json!({"endpoint":endpoint,"tier":tier}), true)?;
        } else {
            #[derive(Serialize)]
            struct Request<'a> {
                endpoint: &'a Endpoint,
                tier: &'a str,
            }
            send(input, &Request { endpoint, tier }, false)?;
        }
        let sent_ns = started.map(|s| s.elapsed().as_nanos());
        let bytes = frame(&mut self.output)?.ok_or("checker ended")?;
        let read_ns = started.map(|s| s.elapsed().as_nanos());
        let result: Value = serde_json::from_slice(&bytes)?;
        let decoded_ns = started.map(|s| s.elapsed().as_nanos());
        if result["model_sha256"] != endpoint.model_sha256
            || result["endpoint_sha256"] != hex(&serde_json::to_vec(endpoint)?)
            || result["tier"] != tier
            || result["checker_binary_sha256"] != self.binary
        {
            return Err("checker receipt binding".into());
        }
        if let Some(started) = started {
            self.profiles
                .push(json!({"request_build_encode_write_flush_ns":sent_ns,
                "response_wait_read_end_ns":read_ns,"response_decode_end_ns":decoded_ns,
                "binding_end_ns":started.elapsed().as_nanos(),"response_bytes":bytes.len(),
                "batched":!self.baseline}));
        }
        self.failed = false;
        Ok(result)
    }
}
impl Drop for Independent {
    fn drop(&mut self) {
        let _scope = optimizer_core::lp_cost::scope("checker_eof_reap");
        self.input.take();
        for _ in 0..100 {
            if self.child.try_wait().ok().flatten().is_some() {
                return;
            }
            std::thread::sleep(Duration::from_millis(2));
        }
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct CheckRequest {
    endpoint: Endpoint,
    tier: String,
}

pub fn check_service(path: &Path) -> Result<()> {
    let started = config::get().profile.then(Instant::now);
    let mut bytes = Vec::new();
    fs::File::open(path)?
        .take((128 << 20) + 1)
        .read_to_end(&mut bytes)?;
    if bytes.len() > 128 << 20 {
        return Err("checker model limit".into());
    }
    let read_ns = started.map(|s| s.elapsed().as_nanos());
    let checker = checker::Checker::new(&bytes)?;
    let prepared_ns = started.map(|s| s.elapsed().as_nanos());
    let original = std::env::var_os("GPUP_CHECKER_ORIGINAL").is_some();
    let binary = hex(&fs::read(std::env::current_exe()?)?);
    let mut output = io::stdout().lock();
    send(
        &mut output,
        &json!({"ready":true,"model_sha256":hex(&bytes),"checker_binary_sha256":binary}),
        control(),
    )?;
    if let Some(started) = started {
        eprintln!(
            "{}",
            json!({"delivery4_checker_setup":{"read_ns":read_ns,"prepared_ns":prepared_ns,
            "ready_ns":started.elapsed().as_nanos()}})
        );
    }
    let mut serial = 0_u64;
    let mut input = io::stdin().lock();
    while let Some(bytes) = frame(&mut input)? {
        let started = config::get().profile.then(Instant::now);
        let request: CheckRequest = serde_json::from_slice(&bytes)?;
        let decoded_ns = started.map(|s| s.elapsed().as_nanos());
        let mut result = checker.assess_mode(&request.endpoint, &request.tier, original)?;
        let assessed_ns = started.map(|s| s.elapsed().as_nanos());
        result["checker_binary_sha256"] = json!(binary);
        send(&mut output, &result, control())?;
        if let Some(started) = started {
            eprintln!(
                "{}",
                json!({"delivery4_checker_assessment":{"serial":serial,
                "decode_ns":decoded_ns,"assessed_ns":assessed_ns,"sent_ns":started.elapsed().as_nanos(),
                "request_bytes":bytes.len(),"batched":!control()}})
            );
        }
        serial += 1;
    }
    Ok(())
}

/// CPU-only end-to-end IPC microprofile; no device or solve is created.
pub fn profile(args: &[String]) -> Result<()> {
    use std::time::Instant;
    if args.len() != 7 {
        return Err("transport-profile MODEL ENDPOINT TIER COUNT OUTPUT".into());
    }
    let endpoint: Endpoint = serde_json::from_slice(&fs::read(&args[3])?)?;
    let count: usize = args[5].parse()?;
    if !(1..=1000).contains(&count) {
        return Err("profile count".into());
    }
    let started = Instant::now();
    let mut child = Independent::spawn(Path::new(&args[2]))?;
    child.ready(&endpoint.model_sha256)?;
    let setup_ns = started.elapsed().as_nanos();
    let mut rows = Vec::new();
    for _ in 0..count {
        let before = Instant::now();
        let certificate = child.assess(&endpoint, &args[4])?;
        rows.push(json!({"ns":before.elapsed().as_nanos(),"certificate":certificate}));
    }
    let before = Instant::now();
    drop(child);
    let value = json!({"setup_ns":setup_ns,"teardown_ns":before.elapsed().as_nanos(),"rows":rows});
    let mut file = fs::OpenOptions::new()
        .write(true)
        .create_new(true)
        .open(&args[6])?;
    file.write_all(&serde_json::to_vec(&value)?)?;
    file.sync_all()?;
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    #[derive(Default)]
    struct Writer {
        bytes: Vec<u8>,
        writes: usize,
    }
    impl Write for Writer {
        fn write(&mut self, bytes: &[u8]) -> io::Result<usize> {
            self.writes += 1;
            self.bytes.extend_from_slice(bytes);
            Ok(bytes.len())
        }
        fn flush(&mut self) -> io::Result<()> {
            Ok(())
        }
    }
    #[test]
    fn batches_exact_bytes_with_signed_zero_and_extremes() {
        let e = Endpoint {
            model_sha256: "a".repeat(64),
            primal: vec![-0.0, 0.0, f64::MAX, f64::MIN_POSITIVE, f64::from_bits(1)],
            dual: vec![1.0; 1024],
            transport: "completed".into(),
        };
        let request = json!({"endpoint":e,"tier":"certified-1e-9"});
        let mut old = Writer::default();
        let mut new = Writer::default();
        send(&mut old, &request, true).unwrap();
        send(&mut new, &request, false).unwrap();
        assert_eq!(old.bytes, new.bytes);
        assert_eq!(new.writes, 1);
        assert!(old.writes > 1000);
        let decoded: CheckRequest = serde_json::from_slice(&new.bytes).unwrap();
        assert_eq!(
            decoded
                .endpoint
                .primal
                .iter()
                .map(|x| x.to_bits())
                .collect::<Vec<_>>(),
            e.primal.iter().map(|x| x.to_bits()).collect::<Vec<_>>()
        );
    }
    #[test]
    fn bounded_frames_distinguish_eof_from_truncation() {
        let mut input = io::Cursor::new(b"{}\n{}\n");
        assert_eq!(frame(&mut input).unwrap().unwrap(), b"{}\n");
        assert_eq!(frame(&mut input).unwrap().unwrap(), b"{}\n");
        assert!(frame(&mut input).unwrap().is_none());
        assert!(frame(&mut io::Cursor::new(b"{}")).is_err());
        let mut over = io::Cursor::new(vec![b'x'; FRAME_LIMIT as usize + 20]);
        assert!(frame(&mut over).is_err());
        assert_eq!(over.position(), FRAME_LIMIT + 1);
        let mut exact = vec![b' '; FRAME_LIMIT as usize];
        *exact.last_mut().unwrap() = b'\n';
        assert_eq!(
            frame(&mut io::Cursor::new(exact)).unwrap().unwrap().len(),
            FRAME_LIMIT as usize
        );
    }
    #[test]
    fn duplicate_unknown_and_nonfinite_requests_refuse() {
        for bytes in [
            br#"{"endpoint":null,"tier":"a","tier":"b"}"#.as_slice(),
            br#"{"endpoint":null,"tier":"a","extra":1}"#,
            br#"{"endpoint":{"primal":[1e999]},"tier":"a"}"#,
        ] {
            assert!(serde_json::from_slice::<CheckRequest>(bytes).is_err());
        }
    }
}

