            || self
                .cancel_file
                .as_ref()
                .is_some_and(|p| Path::new(p).exists())
    }
}
struct Session {
    data: Data,
    ctx: Rc<Context>,
    module: Module,
    stream: Stream,
    pool: BTreeMap<usize, Engine>,
    checker: Independent,
    solve_id: u64,
