//! Immutable process-wide delivery policy; no lane, outcome or timing dispatch.
use crate::Result;
use std::sync::OnceLock;
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Config {
    pub name: &'static str,
    pub batch: bool,
    pub overlap: bool,
    pub profile: bool,
}
static CONFIG: OnceLock<Config> = OnceLock::new();
impl Config {
    pub fn parse(name: &str, profile: &str) -> Result<Self> {
        let (name, batch, overlap) = match name {
            "control" => ("control", false, true),
            "candidate" => ("candidate", false, true),
            _ => return Err("unknown DELIVERY4 variant".into()),
        };
        let profile = match profile {
            "0" => false,
            "1" => true,
            _ => return Err("invalid DELIVERY4 profiling flag".into()),
        };
        Ok(Self {
            name,
            batch,
            overlap,
            profile,
        })
    }
}
pub fn init() -> Result<()> {
    fn env(name: &str, default: &str) -> Result<String> {
        match std::env::var(name) {
            Ok(value) => Ok(value),
            Err(std::env::VarError::NotPresent) => Ok(default.into()),
            Err(error) => Err(error.into()),
        }
    }
    for name in [
        "GPUP_DELIVERY2_CONTROL",
        "GPUP_CHECKER_ORIGINAL",
        "GPUP_DELIVERY3_VARIANT",
        "GPUP_DELIVERY3_PROFILE",
    ] {
        if std::env::var_os(name).is_some() {
            return Err("conflicting retained delivery/checker override".into());
        }
    }
    let config = Config::parse(
        &env("GPUP_DELIVERY4_VARIANT", "control")?,
        &env("GPUP_DELIVERY4_PROFILE", "0")?,
    )?;
    CONFIG
        .set(config)
        .map_err(|_| "delivery configuration already initialized")?;
    Ok(())
}
pub fn get() -> Config {
    *CONFIG.get().unwrap_or(&Config {
        name: "control",
        batch: false,
        overlap: true,
        profile: false,
    })
}
#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn strict_two_variant_policy() {
        for name in ["control", "candidate"] {
            for p in ["0", "1"] {
                let c = Config::parse(name, p).unwrap();
                assert!(c.overlap && !c.batch);
                assert_eq!(c.profile, p == "1");
            }
        }
        assert!(Config::parse("automatic", "0").is_err());
        assert!(Config::parse("control", "yes").is_err());
    }
}

//! Exact SHA-256 binding; the public implementation and numerical code stay frozen.
use sha2::{Digest, Sha256};

pub fn accelerated(bytes: &[u8]) -> String {
    let _scope = optimizer_core::lp_cost::scope("accelerated_artifact_hash");
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let hash = Sha256::digest(bytes);
    let mut output = String::with_capacity(64);
    for value in hash {
        output.push(DIGITS[usize::from(value >> 4)] as char);
        output.push(DIGITS[usize::from(value & 15)] as char);
    }
    output
}

pub fn hex(bytes: &[u8]) -> String {
    if crate::config::get().name == "candidate" {
        accelerated(bytes)
    } else {
        optimizer_experiment::sha256::hex(bytes)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn exact_original_hash_at_padding_and_message_boundaries() {
        for n in [
            0, 1, 2, 55, 56, 57, 63, 64, 65, 119, 120, 127, 128, 129, 4095, 4096, 4097, 65536,
            1048576,
        ] {
            let bytes: Vec<u8> = (0..n).map(|i| ((i * 73 + 19) & 255) as u8).collect();
            assert_eq!(
                accelerated(&bytes),
                optimizer_experiment::sha256::hex(&bytes)
            );
        }
