            };
            for terms in step.terms.chunks(8) {
                local_estimate = local_estimate.max(terms[..7].iter().map(|v| f64::from(*v)).sum());
            }
            events.push(json!({"kind":"window","lane":k,"physical":physical,"logical":e.logical,"step":step}));
