from lp_delivery4_common import ROOT, BASE, load, put, ref, require

EXPECTED = {('lp-delivery4', name) for name in ('optimizer-core','optimizer-cuda-sys','optimizer-experiment','optimizer-lp')} | {('optimizer-cuda-sys','optimizer-core')}

def audit(metadata):
    paths=[];external=[];exceptions=set()
    for package in metadata['packages']:
        manifest=Path(package['manifest_path'])
        if package['source'] is None:
            require(manifest.resolve().is_relative_to(ROOT),'external unbound local package')
            paths.append(ref(manifest))
