    fn tie_even_and_negative_zero() {
        let mut v = vec![0.; 32];
        v[0] = 6.;
        v[1] = 0.25;
        v[2] = 0.75;
        v[3] = -0.25;
        let (w, e, r) = encode(&v, 2).unwrap();
        assert_eq!(e[0], 0);
