fn emit(value: &Value) -> Result<()> {
    let mut out = io::stdout().lock();
    if !config::get().batch {
        serde_json::to_writer(&mut out, value)?;
        out.write_all(b"\n")?;
    } else {
        let mut bytes = serde_json::to_vec(value)?;
        bytes.push(b'\n');
        out.write_all(&bytes)?;
    }
    out.flush()?;
    Ok(())
